// In musepulse_lite//src//viewmodel//main_viewmodel.c
int viewmodel_get_dark_mode_status() {
    return app_settings.dark_mode_enabled;
}

void viewmodel_set_dark_mode_status(int status) {
    if (app_settings.dark_mode_enabled != status) {
        app_settings.dark_mode_enabled = status;
        viewmodel_save_settings();
        events_trigger_event(SETTINGS_UPDATED, NULL);
    }
}

// In musepulse_lite//src//main.c
void draw_settings_page() {
    // ... other settings UI ...
    int current_status = viewmodel_get_dark_mode_status();
    if (ui_draw_checkbox(20, 100, "Enable Dark Mode", &current_status)) {
        viewmodel_set_dark_mode_status(current_status);
    }
}
